files.content:
.root {
  position: relative;
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #3569a8;
  --vt-ink: #0b1f33;
  --vt-ink-soft: #5b6470;
  --vt-on-deep: #ffffff;
  --vt-accent: #7cb8eb;
  --vt-on-accent: #0a2b50;
  --vt-accent-ink: #2f67b8;
  --vt-accent-on-deep: #bfe0f8;
  --vt-line: #e9eaeb;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Fira Sans', 'Open Sans', sans-serif;
  line-height: 1.6;
}

.root *, .root *::before, .root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(ul) {
  list-style: none;
  margin: 0;
  padding: 0;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-family: 'Fira Sans Condensed', 'Fira Sans', sans-serif;
  font-weight: 700;
  line-height: 1.15;
}

.root :where(p) {
  margin: 0;
}

.root img {
  display: block;
  max-width: 100%;
}

.root a:focus-visible {
  outline: 3px solid var(--vt-accent);
  outline-offset: 2px;
}

.container {
  width: min(1140px, 100% - 48px);
  margin-inline: auto;
}

.topbar {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 10px 0;
  font-size: 14px;
}

.topbar .container {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 24px;
}

.topbarText {
  margin: 0;
}

.topbarPhone {
  font-weight: 700;
}

.nav {
  position: absolute;
  top: 48px;
  left: 0;
  right: 0;
  z-index: 10;
  padding: 16px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.logo {
  color: var(--vt-on-deep);
}

.brand {
  font-family: 'Fira Sans Condensed', 'Fira Sans', sans-serif;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 20px;
}

.navLinks a {
  color: var(--vt-on-deep);
  font-size: 15px;
  font-weight: 600;
  padding: 6px 2px;
}

.navLinks a:hover {
  color: var(--vt-accent);
}

.root .navCta {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 10px 22px;
  font-weight: 700;
}

.hero {
  position: relative;
  min-height: 680px;
  display: flex;
  align-items: center;
  padding: 140px 0 160px;
  background-size: cover;
  background-position: center;
  color: var(--vt-on-deep);
  overflow: hidden;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-accent-ink);
  opacity: 0.55;
  pointer-events: none;
}

.heroContent {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  margin-inline: auto;
}

.heroKicker {
  display: inline-block;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--vt-on-deep);
  background: color-mix(in srgb, var(--vt-on-deep) 18%, transparent);
  border-radius: 100px;
  padding: 6px 18px;
}

.heroTitle {
  font-size: clamp(42px, 7vw, 68px);
  line-height: 1.05;
  margin-bottom: 18px;
  color: var(--vt-on-deep);
}

.heroLead {
  font-size: 18px;
  color: var(--vt-on-deep);
  opacity: 0.9;
  margin-bottom: 28px;
  max-width: 560px;
  margin-inline: auto;
}

.heroActions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.root .btnPrimary {
  display: inline-block;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border: 2px solid transparent;
  border-radius: 100px;
  padding: 14px 30px;
  font-size: 16px;
  font-weight: 700;
  transition: transform 0.2s, box-shadow 0.2s;
}

.root .btnPrimary:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px color-mix(in srgb, var(--vt-ink) 18%, transparent);
}

.root .btnGhost {
  display: inline-block;
  background: transparent;
  color: var(--vt-on-deep);
  border: 2px solid var(--vt-on-deep);
  border-radius: 100px;
  padding: 14px 30px;
  font-size: 16px;
  font-weight: 600;
}

.root .btnGhost:hover {
  background: var(--vt-on-deep);
  color: var(--vt-accent-ink);
}

.wave {
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 120px;
  z-index: 2;
  pointer-events: none;
}

.wave path {
  fill: var(--vt-surface);
}

.story {
  padding: 100px 0;
  background: var(--vt-surface);
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.sectionKicker {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--vt-accent-ink);
  margin-bottom: 12px;
}

.sectionTitle {
  font-size: clamp(30px, 4vw, 46px);
  color: var(--vt-ink);
  margin-bottom: 20px;
}

.storyIntro {
  font-size: 18px;
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.storyParagraph {
  color: var(--vt-ink-soft);
  margin-bottom: 12px;
}

.storyMedia {
  position: relative;
}

.storyImage {
  width: 100%;
  border-radius: 20px;
  object-fit: cover;
  box-shadow: 0 24px 50px color-mix(in srgb, var(--vt-ink) 14%, transparent);
}

.callCard {
  position: absolute;
  right: 24px;
  bottom: 24px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 12px;
  padding: 22px 26px;
  box-shadow: 0 12px 30px color-mix(in srgb, var(--vt-ink) 16%, transparent);
}

.callCard strong {
  display: block;
  font-size: 16px;
  margin-bottom: 4px;
}

.callCard a {
  font-size: 22px;
  font-weight: 800;
}

.services {
  background: var(--vt-surface-2);
  padding: 100px 0;
}

.sectionHead {
  max-width: 640px;
  margin-bottom: 48px;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.serviceCard {
  background: var(--vt-surface);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 30px color-mix(in srgb, var(--vt-ink) 8%, transparent);
  display: grid;
  grid-template-columns: 5fr 7fr;
  align-items: stretch;
  transition: transform 0.2s, box-shadow 0.2s;
}

.serviceCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 40px color-mix(in srgb, var(--vt-ink) 14%, transparent);
}

.serviceMedia {
  min-height: 220px;
  height: 100%;
}

.serviceMedia img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.serviceInfo {
  padding: 28px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.serviceNum {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--vt-accent-ink);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.serviceTitle {
  font-size: 22px;
  color: var(--vt-ink);
  margin-bottom: 10px;
}

.serviceDesc {
  color: var(--vt-ink-soft);
  line-height: 1.65;
}

.contact {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 100px 0;
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: center;
}

.contact .sectionKicker {
  color: var(--vt-accent-on-deep);
}

.contact .sectionTitle {
  color: var(--vt-on-deep);
}

.contactText {
  color: var(--vt-on-deep);
  opacity: 0.9;
  margin-bottom: 12px;
}

.contactPhone {
  display: inline-block;
  font-size: 32px;
  font-weight: 800;
  color: var(--vt-on-deep);
  margin-bottom: 12px;
}

.contactHours {
  color: var(--vt-on-deep);
  opacity: 0.85;
  margin-bottom: 16px;
}

.socialInline {
  margin-top: 12px;
}

.mapWrap {
  background: var(--vt-surface);
  border-radius: 20px;
  overflow: hidden;
  min-height: 320px;
  box-shadow: 0 20px 40px color-mix(in srgb, var(--vt-ink) 18%, transparent);
}

.footer {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding-top: 60px;
}

.footerTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 30px;
}

.footerBrand {
  font-size: 20px;
  font-weight: 800;
}

.footerTag {
  opacity: 0.85;
}

.footerGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  padding: 30px 0 40px;
  border-top: 1px solid color-mix(in srgb, var(--vt-on-accent) 25%, transparent);
}

.footerCol h4 {
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 16px;
}

.footerCol li + li,
.footerCol p + p {
  margin-top: 8px;
}

.footerCol a {
  font-weight: 600;
}

.footerBottom {
  border-top: 1px solid color-mix(in srgb, var(--vt-on-accent) 25%, transparent);
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 14px;
  opacity: 0.9;
}

.callFab {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 14px 22px;
  font-weight: 800;
  box-shadow: 0 16px 32px color-mix(in srgb, var(--vt-ink) 22%, transparent);
}

.callFabIcon {
  font-size: 20px;
}

@media (max-width: 991px) {
  .hero {
    padding: 100px 0 120px;
  }

  .storyGrid,
  .contactGrid {
    grid-template-columns: 1fr;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }

  .footerGrid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

@media (max-width: 767px) {
  .topbar .container {
    justify-content: center;
  }

  .topbarText:nth-child(2) {
    display: none;
  }

  .nav {
    position: relative;
    top: 0;
    background: var(--vt-surface);
  }

  .navIn {
    flex-direction: column;
    align-items: flex-start;
  }

  .logo {
    color: var(--vt-accent-ink);
  }

  .navLinks {
    flex-wrap: wrap;
    gap: 8px 14px;
  }

  .navLinks a {
    color: var(--vt-ink);
  }

  .hero {
    padding: 80px 0 100px;
    min-height: 560px;
  }

  .serviceCard {
    grid-template-columns: 1fr;
  }

  .serviceMedia {
    min-height: 180px;
  }

  .callCard {
    right: 12px;
    bottom: 12px;
    padding: 14px 16px;
  }

  .callFab {
    right: 12px;
    bottom: 12px;
    padding: 12px 16px;
  }

  .footerBottom {
    flex-direction: column;
  }
}
